def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    if color and platform.system() in SUPPORTED_PLATFORMS:
        master, slave = pty.openpty()
    else:
        master = slave = None

    processes = []
    for i in range(target_concurrency):
        p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kwargs)
        processes.append(p)

    for arg in varargs:
        if master is not None:
            os.write(master, arg.encode())
        else:
            p.stdin.write(arg)

    for p in processes:
        p.stdin.close()

    output = []
    for p in processes:
        out, err = p.communicate()
        output.append(out)

    return (p.returncode, b''.join(output))

