def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        freq = defaultdict(set)
        hits = defaultdict(int)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
                freq[key].add(len(cache))
            else:
                hits[key] += 1
                freq[key].remove(len(cache))
                freq[key].add(len(cache))
            if len(cache) > maxsize:
                # least frequently used
                for key in freq:
                    if len(freq[key]) == 1:
                        break
                del cache[key]
                del freq[key]
            return cache[key]
        return wrapper
    return decorator

