        if field["type"] == "dict":
            if field["name"] not in last_applied_manifest:
                last_applied_manifest[field["name"]] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field["name"]], field["schema"], response[field["name"]])
        elif field["type"] == "list":
