def isoparse(dt_str):
    # Initialize variables
    date_str, time_str, tz_str = None, None, None
    date_format, time_format = None, None
    date_components, time_components = None, None
    tz_components = None

    # Split the input string into date, time, and time zone components
    if "T" in dt_str:
        date_str, time_str = dt_str.split("T")
    else:
        date_str = dt_str

    # Check if the input string contains a time zone offset
    if "Z" in dt_str:
        tz_str = "Z"
    elif "+" in dt_str or "-" in dt_str:
        tz_str = dt_str.split("+")[-1]

    # Parse the date and time components
    if date_str:
        date_format = "%Y-%m-%d"
        date_components = datetime.datetime.strptime(date_str, date_format)

    if time_str:
        time_format = "%H:%M:%S.%f"
        time_components = datetime.datetime.strptime(time_str, time_format)

    # Create a datetime object from the date and time components
    if date_components and time_components:
        dt = datetime.datetime(date_components.year, date_components.month, date_components.day, time_components.hour, time_components.minute, time_components.second, time_components.microsecond)
    elif date_components:
        dt = datetime.datetime(date_components.year, date_components.month, date_components.day)
    elif time_components:
        dt = datetime.datetime(time_components.hour, time_components.minute, time_components.second, time_components.microsecond)

    # Apply the time zone offset
    if tz_str:
        tz_components = datetime.datetime.strptime(tz_str, "%H:%M")
        tz = datetime.timezone(datetime.timedelta(hours=tz_components.hour, minutes=tz_components.minute))
        dt = dt.replace(tzinfo=tz)

    return dt

