def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Verify the signature using the public key
    if not public_key.verify(signature, doc):
        raise ValueError("Invalid signature")

    # Verify the signature is valid for the claimed author
    author = doc.find("author")
    if author is None:
        raise ValueError("Missing author element")
    if author.text != public_key.name:
        raise ValueError("Invalid author")

    # Verify the signature is valid for the claimed message
    message = doc.find("message")
    if message is None:
        raise ValueError("Missing message element")
    if message.text != "Hello, world!":
        raise ValueError("Invalid message")

