    return {
        "option1": ["option2", "option3"],
        "option4": ["option5", "option6"],
        "option7": ["option8", "option9"]
    }

def validate_arg_deprecation(cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """

    # Check if any of the arguments in cli_args are deprecated
    for arg in cli_args:
        if arg in DEPRECATED_ARGS:
            print(f"Warning: {arg} is deprecated and will be removed in a future version. Please use {DEPRECATED_ARGS[arg]} instead.")

    # Check if any of the arguments in answer_file_args are deprecated
    for arg in answer_file_args:
        if arg in DEPRECATED_ARGS:
            print(f"Warning: {arg} is deprecated and will be removed in a future version. Please use {DEPRECATED_ARGS[arg]} instead.")

    # If any of the arguments are deprecated, raise a ValueError
    if any(arg in DEPRECATED_ARGS for arg in cli_args) or any(arg in DEPRECATED_ARGS for arg in answer_file_args):
        raise ValueError("Deprecated arguments detected. Please update your arguments.")

def get_silent_args(self, args):
    silent_args = []
    for arg in args:
        if arg.startswith("-"):
            silent_args.append(arg)
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required_args = [arg for arg in self.args if arg.required]
    provided_args = [arg for arg in args if arg in self.args]
    return len(required_args) == len(provided_args)

def _get_conditionally_required_args(command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        if option.get("required_when") and option["required_when"] in args:
            required_args.append(option["name"])
    return required_args

def validate_length_args(self, args):
    for arg in args:
        if len(arg) > self.max_length:
            raise ValueError(f"Argument {arg} is too long, maximum length is {self.max_length}")

def validate_choices_args(self, args):
    for arg in args:
        if arg not in self.available_choices:
            raise ValueError(f"Invalid choice: {arg}. Must be one of {self.available_choices}")

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg < self.min_value or arg > self.max_value:
            raise ValueError(f"Invalid argument value: {arg}. Must be between {self.min_value} and {self.max_value}.")
    return args

def get_nested_custom_and_control_args(args):
    control_args = {}
    nested_args = {}
    for arg in args:
        if arg.startswith("control_"):
            control_args[arg] = args[arg]
        elif arg.startswith("nested_"):
            nested_args[arg] = args[arg]
        else:
            nested_args[arg] = args[arg]
    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is not None:
        for var in extra_vars:
            vars_dict[var] = True

def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Cast arguments to correct types
    for key, value in values_dict.items():
        if key in ["--port", "-p"]:
            values_dict[key] = int(value)
        elif key in ["--host", "-h"]:
            values_dict[key] = str(value)
        elif key in ["--username", "-u"]:
            values_dict[key] = str(value)
        elif key in ["--password", "-p"]:
            values_dict[key] = str(value)
        elif key in ["--timeout", "-t"]:
            values_dict[key] = int(value)
        elif key in ["--verbose", "-v"]:
            values_dict[key] = bool(value)
        else:
            values_dict[key] = str(value)

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = {}
    with open(plugin_dir + '/plugin.json') as f:
        plugin_spec = json.load(f)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[key + '.' + subkey] = subvalue
        else:
            flatten_dict[key] = value
    return flatten_dict

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
